// Encoding createLaunch Argus harus persis sama dengan calldata tx nyata di Arc (tanpa network).
// Fixture: tx 0x84f1413e7e531531262cd332f0caef090210f712fc75ec2ca5519ef1d1cc789a (BUSI, dev buy 0.002 USDC, buy tax 2%, sell 3%).
import { test } from "node:test";
import assert from "node:assert/strict";
import { ethers } from "ethers";
import { CFG } from "../src/config.js";
import { estimateDevBuy } from "../src/chains/argus.js";

const coder = ethers.AbiCoder.defaultAbiCoder();
const CREATE_TYPES = [
  "tuple(string name,string symbol,uint256 totalSupply,uint256 startMcap,uint256 bondMcap,uint16 buyTaxBps,uint16 sellTaxBps,uint16 creatorFundsBps,uint16 buybackBurnBps,uint16 dividendsBps,uint16 liquidityBps,uint256 devBuyAmount,address quoteAsset,uint256 flag)",
  "tuple(string imageURI,string website,string twitter,string telegram,string description)",
  "bytes32", "bytes32",
];

const REAL_INPUT = "";

test("CREATE_TYPES decode → encode menghasilkan calldata identik dengan tx nyata", () => {
  const [p1, p2, tokenSalt, hookSalt] = coder.decode(CREATE_TYPES, "0x" + REAL_INPUT.slice(10));
  assert.equal(p1.name, "BUSI");
  assert.equal(p1.symbol, "BUSI");
  assert.equal(p1.totalSupply, CFG.argus.totalSupply);
  assert.equal(p1.startMcap, CFG.argus.startMcap);
  assert.equal(p1.bondMcap, CFG.argus.bondMcap);
  assert.equal(p1.buyTaxBps, 200n);
  assert.equal(p1.sellTaxBps, 300n);
  assert.equal(p1.creatorFundsBps + p1.buybackBurnBps + p1.dividendsBps + p1.liquidityBps, 10000n);
  assert.equal(p1.devBuyAmount, 2_000n);
  assert.equal(p1.quoteAsset.toLowerCase(), CFG.argus.usdc);
  assert.equal(p1.flag, CFG.argus.launchFlag);
  assert.equal(p2.imageURI.slice(0, 7), "ipfs://");
  const re = "0x11b8f0f1" + coder.encode(CREATE_TYPES, [p1, p2, tokenSalt, hookSalt]).slice(2);
  assert.equal(re, REAL_INPUT);
});

test("estimateDevBuy cocok dengan event dev-buy tx nyata (< 0.1%)", () => {
  // (usdcIn, buyTaxBps, tokensOut riil dari event 0x84d429ed…)
  const cases = [
    [4_000_000n, 100, ethers.parseEther("1577813.658161971535663569")],
    [450_000_000n, 200, ethers.parseEther("149198081.660700597548096977")],
    [2_000n, 200, ethers.parseEther("782.184056683691113151")],
  ];
  for (const [usdcIn, tax, real] of cases) {
    const est = estimateDevBuy(usdcIn, tax);
    const diffBps = Number(((est > real ? est - real : real - est) * 10_000n) / real);
    assert.ok(diffBps < 10, `usdcIn ${usdcIn}: selisih ${diffBps} bps (est ${est}, real ${real})`);
  }
  assert.equal(estimateDevBuy(0n, 100), 0n);
});
